import numpy as np

# 每个钱包的金额分布 - 只用少量统计量
tx_sample = tx_df.sample(frac=0.2, random_state=42)

def compute_skew(group):
    a = group['amount'].values
    if len(a) < 3:
        return 0.0
    return pd.Series(a).skew()

def compute_kurt(group):
    a = group['amount'].values
    if len(a) < 3:
        return 0.0
    return pd.Series(a).kurtosis()

skew = tx_sample.groupby('src').apply(compute_skew).reset_index()
skew.columns = ['wallet_id', 'amount_skew']

kurt = tx_sample.groupby('src').apply(compute_kurt).reset_index()
kurt.columns = ['wallet_id', 'amount_kurt']

# 金额的离散度：max/min比
def compute_range_ratio(group):
    a = group['amount'].values
    if len(a) < 2 or a.min() <= 0:
        return 0.0
    return a.max() / a.min()

range_ratio = tx_sample.groupby('src').apply(compute_range_ratio).reset_index()
range_ratio.columns = ['wallet_id', 'amount_max_min_ratio']

risk_src = tx_sample[tx_sample['is_risk']==1]['src'].unique()

for df_stats in [skew, kurt, range_ratio]:
    df_stats['is_risk'] = df_stats['wallet_id'].isin(risk_src).astype(int)

results = {}
for col, df in [('amount_skew', skew), ('amount_kurt', kurt), ('amount_max_min_ratio', range_ratio)]:
    normal_vals = df[df['is_risk']==0][col]
    abnormal_vals = df[df['is_risk']==1][col]
    results[f'{col}_normal_mean'] = normal_vals.mean()
    results[f'{col}_abnormal_mean'] = abnormal_vals.mean()

# 金额中位数与众数的差异
def median_vs_mode(group):
    a = group['amount'].values
    if len(a) < 3:
        return 0.0
    median = np.median(a)
    # 分桶找众数
    bins = np.arange(0, a.max() + 100, 100)
    if len(bins) < 2:
        return 0.0
    counts, _ = np.histogram(a, bins=bins)
    mode_bin = bins[counts.argmax()]
    return abs(median - mode_bin) / (median + 1)

med_mode = tx_sample.groupby('src').apply(median_vs_mode).reset_index()
med_mode.columns = ['wallet_id', 'median_mode_diff']
med_mode['is_risk'] = med_mode['wallet_id'].isin(risk_src).astype(int)
results['median_mode_diff_normal'] = med_mode[med_mode['is_risk']==0]['median_mode_diff'].mean()
results['median_mode_diff_abnormal'] = med_mode[med_mode['is_risk']==1]['median_mode_diff'].mean()

query_result = pd.Series(results)

import numpy as np

# 每个钱包的交易时间是否集中在特定星期几
tx_sample = tx_df.sample(frac=0.2, random_state=42).copy()
tx_sample['dow'] = pd.to_datetime(tx_sample['timestamp']).dt.dayofweek

def compute_dow_concentration(group):
    counts = group['dow'].value_counts()
    if len(counts) == 0:
        return 0.0
    return counts.max() / counts.sum()

dow_conc = tx_sample.groupby('src').apply(compute_dow_concentration).reset_index()
dow_conc.columns = ['wallet_id', 'dow_concentration']

# 交易时间是否集中在特定小时段
def compute_hour_concentration(group):
    counts = group['hour'].value_counts()
    if len(counts) == 0:
        return 0.0
    return counts.max() / counts.sum()

