def mode_conc(intervals):
    if len(intervals) < 5:
        return 0.0
    bins = np.arange(0, max(intervals) + 10, 10)
    if len(bins) < 2:
        return 0.0
    counts, _ = np.histogram(intervals, bins=bins)
    if counts.sum() == 0:
        return 0.0
    return counts.max() / counts.sum()

conc_vals = {}
